  1→/**
  2→ * Payment Dynamics Chart Component
  3→ *
  4→ * Displays payment trends over time using an AreaChart.
  5→ * Features:
  6→ * - Time-series visualization of paid amounts
  7→ * - Group by day/week/month
  8→ * - Date range presets (7/30/90 days)
  9→ * - Tooltip with date, amount, and payment count
 10→ * - Loading, error, and empty states
 11→ */
 12→
 13→"use client"
 14→
 15→import { useQuery } from '@tanstack/react-query';
 16→import { useState, useMemo } from 'react';
 17→import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
 18→import { Skeleton } from '@/components/ui/skeleton';
 19→import { Button } from '@/components/ui/button';
 20→import {
 21→  Select,
 22→  SelectContent,
 23→  SelectItem,
 24→  SelectTrigger,
 25→  SelectValue,
 26→} from '@/components/ui/select';
 27→import {
 28→  ChartContainer,
 29→  ChartTooltip,
 30→  ChartTooltipContent,
 31→} from '@/components/ui/chart';
 32→import { AreaChart, Area, XAxis, YAxis, CartesianGrid, ResponsiveContainer } from 'recharts';
 33→import { analyticsApi } from '@/lib/api/analytics';
 34→import type { PaymentDynamicsQueryParams, PaymentDynamicsResponse, PaymentDynamicsPoint } from '@/types/fastapi';
 35→
 36→// =============================================================================
 37→// Constants
 38→// =============================================================================
 39→
 40→const CHART_CONFIG = {
 41→  paidAmount: {
 42→    label: 'Оплачено',
 43→    color: 'hsl(var(--chart-1))',
 44→  } as const,
 45→};
 46→
 47→const GROUP_BY_OPTIONS = [
 48→  { value: 'day', label: 'День' },
 49→  { value: 'week', label: 'Неделя' },
 50→  { value: 'month', label: 'Месяц' },
 51→] as const;
 52→
 53→const DATE_RANGES = [
 54→  { value: 7, label: '7 дней' },
 55→  { value: 30, label: '30 дней' },
 56→  { value: 90, label: '90 дней' },
 57→] as const;
 58→
 59→type GroupByValue = 'day' | 'week' | 'month';
 60→
 61→// =============================================================================
 62→// Helpers
 63→// =============================================================================
 64→
 65→const currencyFormatter = new Intl.NumberFormat('ru-RU', {
 66→  style: 'currency',
 67→  currency: 'RUB',
 68→  minimumFractionDigits: 0,
 69→  maximumFractionDigits: 0,
 70→});
 71→
 72→function formatDate(dateStr: string, groupBy: GroupByValue): string {
 73→  const date = new Date(dateStr);
 74→  switch (groupBy) {
 75→    case 'day':
 76→      return date.toLocaleDateString('ru-RU', { day: '2-digit', month: '2-digit' });
 77→    case 'week':
 78→      return date.toLocaleDateString('ru-RU', { day: '2-digit', month: 'short' });
 79→    case 'month':
 80→      return date.toLocaleDateString('ru-RU', { month: 'short', year: '2-digit' });
 81→    default:
 82→      return dateStr;
 83→  }
 84→}
 85→
 86→function getDateRange(days: number): { period_start: string; period_end: string } {
 87→  const end = new Date();
 88→  const start = new Date();
 89→  start.setDate(end.getDate() - days);
 90→  return {
 91→    period_start: start.toISOString().split('T')[0],
 92→    period_end: end.toISOString().split('T')[0],
 93→  };
 94→}
 95→
 96→// =============================================================================
 97→// Component
 98→// =============================================================================
 99→
100→export function PaymentDynamicsChart() {
101→  const [groupBy, setGroupBy] = useState<GroupByValue>('day');
102→  const [dateRange, setDateRange] = useState(30);
103→
104→  const queryParams = useMemo<PaymentDynamicsQueryParams>(() => ({
105→    group_by: groupBy,
106→    ...getDateRange(dateRange),
107→  }), [groupBy, dateRange]);
108→
109→  const { data, isLoading, error, isError } = useQuery({
110→    queryKey: ['analytics', 'payment-dynamics', queryParams],
111→    queryFn: () => analyticsApi.getPaymentDynamics(queryParams),
112→    refetchInterval: 60000,
113→  });
114→
115→  const chartData = useMemo(() => {
116→    if (!data?.data) return [];
117→    return data.data.data.map((point: PaymentDynamicsPoint) => ({
118→      date: formatDate(point.date, groupBy),
119→      paidAmount: point.paid_amount,
120→      paidCount: point.paid_count,
121→      originalDate: point.date,
122→    }));
123→  }, [data?.data, groupBy]);
124→
125→  const isEmpty = chartData.length === 0;
126→
127→  if (isLoading) {
128→    return <PaymentDynamicsChartSkeleton />;
129→  }
130→
131→  if (isError || error) {
132→    return (
133→      <Card>
134→        <CardHeader>
135→          <CardTitle>Динамика платежей</CardTitle>
136→        </CardHeader>
137→        <CardContent>
138→          <p className="text-sm text-destructive">
139→            {error instanceof Error ? error.message : 'Не удалось загрузить данные динамики платежей'}
140→          </p>
141→        </CardContent>
142→      </Card>
143→    );
144→  }
145→
146→  if (isEmpty) {
147→    return (
148→      <Card>
149→        <CardHeader>
150→          <CardTitle>Динамика платежей</CardTitle>
151→        </CardHeader>
152→        <CardContent>
153→          <div className="flex flex-col items-center justify-center py-8 text-center">
154→            <p className="text-sm text-muted-foreground mb-4">
155→              Нет данных о платежах за выбранный период
156→            </p>
157→            <p className="text-xs text-muted-foreground">
158→              Попробуйте выбрать другой период или группировку
159→            </p>
160→          </div>
161→        </CardContent>
162→      </Card>
163→    );
164→  }
165→
166→  return (
167→    <Card>
168→      <CardHeader>
169→        <div className="flex items-center justify-between">
170→          <CardTitle>Динамика платежей</CardTitle>
171→          <div className="flex items-center gap-2">
172→            <Select value={String(dateRange)} onValueChange={(v) => setDateRange(Number(v))}>
173→              <SelectTrigger className="w-[100px] h-8">
174→                <SelectValue />
175→              </SelectTrigger>
176→              <SelectContent>
177→                {DATE_RANGES.map((range) => (
178→                  <SelectItem key={range.value} value={String(range.value)}>
179→                    {range.label}
180→                  </SelectItem>
181→                ))}
182→              </SelectContent>
183→            </Select>
184→            <Select value={groupBy} onValueChange={(v) => setGroupBy(v as GroupByValue)}>
185→              <SelectTrigger className="w-[100px] h-8">
186→                <SelectValue />
187→              </SelectTrigger>
188→              <SelectContent>
189→                {GROUP_BY_OPTIONS.map((option) => (
190→                  <SelectItem key={option.value} value={option.value}>
191→                    {option.label}
192→                  </SelectItem>
193→                ))}
194→              </SelectContent>
195→            </Select>
196→          </div>
197→        </div>
198→      </CardHeader>
199→      <CardContent>
200→        <ChartContainer config={CHART_CONFIG} className="h-[300px]">
201→          <ResponsiveContainer width="100%" height="100%">
202→            <AreaChart data={chartData}>
203→              <CartesianGrid strokeDasharray="3 3" className="stroke-muted" />
204→              <XAxis
205→                dataKey="date"
206→                tick={{ fill: 'hsl(var(--muted-foreground))' }}
207→                tickLine={{ stroke: 'hsl(var(--border))' }}
208→                className="text-xs"
209→              />
210→              <YAxis
211→                tick={{ fill: 'hsl(var(--muted-foreground))' }}
212→                tickLine={{ stroke: 'hsl(var(--border))' }}
213→                tickFormatter={(value) => {
214→                  if (value >= 1000000) return `${(value / 1000000).toFixed(1)}M`;
215→                  if (value >= 1000) return `${(value / 1000).toFixed(0)}K`;
216→                  return String(value);
217→                }}
218→                className="text-xs"
219→              />
220→              <ChartTooltip
221→                content={<ChartTooltipContent />}
222→                formatter={(value: number, name: string) => [
223→                  currencyFormatter.format(value),
224→                  CHART_CONFIG.paidAmount.label,
225→                ]}
226→                labelFormatter={(label: string, payload: any) => {
227→                  const point = payload?.[0]?.payload;
228→                  if (!point) return label;
229→                  const date = new Date(point.originalDate).toLocaleDateString('ru-RU', {
230→                    day: 'numeric',
231→                    month: 'long',
232→                    year: 'numeric',
233→                  });
234→                  return `${date} • ${point.paidCount} платеж(ей)`;
235→                }}
236→              />
237→              <Area
238→                type="monotone"
239→                dataKey="paidAmount"
240→                stroke="hsl(var(--chart-1))"
241→                fill="hsl(var(--chart-1))"
242→                fillOpacity={0.3}
243→                name={CHART_CONFIG.paidAmount.label}
244→              />
245→            </AreaChart>
246→          </ResponsiveContainer>
247→        </ChartContainer>
248→      </CardContent>
249→    </Card>
250→  );
251→}
252→
253→// =============================================================================
254→// Skeleton
255→// =============================================================================
256→
257→function PaymentDynamicsChartSkeleton() {
258→  return (
259→    <Card>
260→      <CardHeader>
261→        <div className="flex items-center justify-between">
262→          <CardTitle>
263→            <Skeleton className="h-6 w-40" />
264→          </CardTitle>
265→          <div className="flex items-center gap-2">
266→            <Skeleton className="h-8 w-[100px]" />
267→            <Skeleton className="h-8 w-[100px]" />
268→          </div>
269→        </div>
270→      </CardHeader>
271→      <CardContent>
272→        <Skeleton className="h-[300px] w-full" />
273→      </CardContent>
274→    </Card>
275→  );
276→}
277→

